int main(int argc,char **argv){gtk_init(&argc,&argv);window=dove_form("DoveOS SDK 2 Preview - Controls Demo",740,540);GtkWidget *box=sdk_controls_page(window);gtk_container_add(GTK_CONTAINER(window),box);gtk_widget_show_all(window);if(argc>1&&!strcmp(argv[1],"--dialogs")){gtk_notebook_set_current_page(GTK_NOTEBOOK(book),1);}if(argc>1&&!strcmp(argv[1],"--tray-preview")){gtk_notebook_set_current_page(GTK_NOTEBOOK(book),4);gtk_toggle_button_set_active(GTK_TOGGLE_BUTTON(check_tray),TRUE);}if(argc>1&&!strcmp(argv[1],"--smoke-test")){gtk_status_icon_set_visible(tray,TRUE);busy(NULL,NULL);dove_timer(3500,smoke_done,NULL);}gtk_main();return test_result;}

